package com.bank.feeaudit.service;

import java.util.Collections;
import java.util.PriorityQueue;
import java.util.logging.Logger;

// Finds the Kth smallest fee using a size-K max-heap.
public class FeeAuditService {
    private static final Logger log = Logger.getLogger(FeeAuditService.class.getName());

    public int kthSmallest(int[] fees, int k) {
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
        for (int i = 0; i < k; i++) maxHeap.offer(fees[i]);   // seed with first K
        for (int i = k; i < fees.length; i++) {
            if (fees[i] < maxHeap.peek()) {                    // smaller than largest kept
                maxHeap.poll();
                maxHeap.offer(fees[i]);
            }
        }
        final int kth = maxHeap.peek();                        // largest of the K smallest
        log.info(() -> k + "th smallest fee = " + kth);
        return kth;
    }
}
